import unittest

from duration import parse_duration


class ParseDurationTests(unittest.TestCase):
    def test_single_units(self):
        self.assertEqual(parse_duration("0s"), 0)
        self.assertEqual(parse_duration("45s"), 45)
        self.assertEqual(parse_duration("2m"), 120)
        self.assertEqual(parse_duration("3h"), 10800)

    def test_combined(self):
        self.assertEqual(parse_duration("1h30m"), 5400)
        self.assertEqual(parse_duration("1h2m3s"), 3723)

    def test_any_order(self):
        self.assertEqual(parse_duration("30m1h"), 5400)
        self.assertEqual(parse_duration("3s2m1h"), 3723)

    def test_whitespace_between_pairs(self):
        self.assertEqual(parse_duration("1h 30m"), 5400)
        self.assertEqual(parse_duration("1h\t30m  5s"), 5405)
        self.assertEqual(parse_duration("  10s  "), 10)

    def test_zero_and_large_values(self):
        self.assertEqual(parse_duration("0h0m0s"), 0)
        self.assertEqual(parse_duration("100m"), 6000)
        self.assertEqual(parse_duration("007s"), 7)

    def test_rejects_empty(self):
        for text in ["", " ", "\t\n"]:
            with self.assertRaises(ValueError, msg=repr(text)):
                parse_duration(text)

    def test_rejects_unknown_units(self):
        for text in ["5d", "1x", "1hr", "10ms", "1H", "5", "h"]:
            with self.assertRaises(ValueError, msg=repr(text)):
                parse_duration(text)

    def test_rejects_signs(self):
        for text in ["-5s", "+5s", "1h-30m", "1h+30m"]:
            with self.assertRaises(ValueError, msg=repr(text)):
                parse_duration(text)

    def test_rejects_decimals(self):
        for text in ["1.5h", "0.5s", "1h.5m"]:
            with self.assertRaises(ValueError, msg=repr(text)):
                parse_duration(text)

    def test_rejects_repeated_units(self):
        for text in ["1h1h", "1s 2s", "1m2s3m"]:
            with self.assertRaises(ValueError, msg=repr(text)):
                parse_duration(text)

    def test_rejects_trailing_or_leading_junk(self):
        for text in ["1h30", "1h!", "1h30m x", "x1h", "1h,30m", "1 h"]:
            with self.assertRaises(ValueError, msg=repr(text)):
                parse_duration(text)

    def test_rejects_non_string(self):
        with self.assertRaises(ValueError):
            parse_duration(None)


if __name__ == "__main__":
    unittest.main()
